import{_ as a}from"./chunks/L0C2L1_Function_Combination.Cu87uvNS.js";import{_ as s,o as e,a as n,b as l}from"./app.DKoEZOcr.js";const i="/ascendc.github.io/pr/5487/assets/L0C2L1_Function_Combination_DataCopy_950.Cy5E0y_k.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬出","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/cube_compute_store"},{"text":"DataCopy（L0C到L1数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToL1"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToL1.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToL1.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),p={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToL1.md"};function r(d,t,c,o,_,h){return e(),n("div",null,[...t[0]||(t[0]=[l('<div><article class="markdown-body"><h1>DataCopy（L0C到L1数据搬运）<a id="ZH-CN_TOPIC_0000002538231198"></a></h1><h2 id="产品支持情况">产品支持情况<a id="zh-cn_topic_0000002511188540_section796754519912"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="zh-cn_topic_0000002511188540_section106841136114319"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>矩阵计算的结果存放在L0C Buffer，DataCopy接口用于将结果搬运至L1 Buffer中，并且在搬运过程中支持随路格式转换等操作。</p><div data-filter="950,A3,910b"><p>下图展示了随路量化、随路ReLU、随路通道合并的有效组合、中间数据类型和数据路径。下图中的F32-&gt;F16与F32-&gt;BF16为非量化模式，仅为Cast，其余为随路scalar/tensor量化模式。</p><div data-filter="A3,910b"><p><strong>图1</strong> L0C2L1流程图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）<a id="zh-cn_topic_0000002511188540_fig8956371257"></a></p><p><img src="'+a+'" alt></p></div><div data-filter="950"><p><strong>图2</strong> L0C2L1流程图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）<a id="zh-cn_topic_0000002542828493_fig1828513492475"></a></p><p><img src="'+i+`" alt></p></div></div><h2 id="函数原型">函数原型<a id="zh-cn_topic_0000002511188540_section82039854412"></a><a class="header-anchor" href="#函数原型">​</a></h2><p>DataCopy矩阵搬出接口支持多种随路能力的组合，需要设置不同的寄存器，配合数据搬运指令开启不同的数据搬运能力，对应的接口如下：</p><ul><li><p>数据搬运接口，通路L0C Buffer(CO1)-&gt;L1 Buffer(C1)，配合设置寄存器实现量化和ReLU激活。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyCO12DstParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li><li><p><a href="../cube_store_aux_config/SetFixPipeConfig.html">SetFixPipeConfig</a>：寄存器设置接口，通过调用该接口设置随路量化，其中tensor的每个元素都代表一个量化参数，使用tensor量化时需要设置。</p></li><li><p><a href="../cube_store_aux_config/SetFixpipePreQuantFlag.html">SetFixpipePreQuantFlag</a>：寄存器设置接口，通过调用该接口设置随路量化参数，此元素代表整个输出矩阵使用的量化参数，使用Scalar量化时需要设置。</p></li><li><p><a href="../cube_store_aux_config/SetFixpipeNz2ndFlag.html">SetFixpipeNz2ndFlag</a>：寄存器设置接口，通过调用该接口设置随路NZ2ND格式转换配置，使用随路NZ2ND需要设置。</p></li></ul><div data-filter="310b"><p>针对Atlas 200I/500 A2 推理产品，还支持如下两个接口：</p><ul><li><p><a href="../cube_store_aux_config/SetFixPipeClipRelu.html">SetFixPipeClipRelu</a>：寄存器设置接口，通过调用该接口设置ClipReLU操作的最大值。</p></li><li><p><a href="../cube_store_aux_config/SetFixPipeAddr.html">SetFixPipeAddr</a>：寄存器设置接口，通过调用该接口设置Elementwise操作时LocalTensor的地址。</p></li></ul></div><h2 id="参数说明">参数说明<a id="zh-cn_topic_0000002511188540_section16128134420472"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 数据搬运DataCopy模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数的数据类型。支持的数据类型请参考<a href="#zh-cn_topic_0000002511188540_section4219135304818">数据类型</a>。</td></tr><tr><td>U</td><td>源操作数的数据类型。支持的数据类型请参考<a href="#zh-cn_topic_0000002511188540_section4219135304818">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 数据搬运DataCopy接口参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，数据格式为NZ<span data-filter="950">、ND（仅Ascend 950PR/Ascend 950DT支持）</span>格式，地址需要满足32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，支持的物理地址为L0C Buffer（TPosition为CO1），为Mmad接口计算的结果。数据格式为NZ格式，地址需要满足64字节对齐。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数，类型为<a href="#zh-cn_topic_0000002511188540_table35908519282">DataCopyCO12DstParams</a>。<br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表3</strong> DataCopyCO12DstParams结构体参数定义<a id="zh-cn_topic_0000002511188540_table35908519282"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>sid</td><td>此参数用户无需关注，设置为0即可。</td></tr><tr><td>nSize</td><td>源NZ矩阵在N方向上的大小。取值范围nSize∈[0, 4095]，nSize必须为16的倍数。<br><strong>注：nSize=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>mSize</td><td>源NZ矩阵在M方向上的大小。<br>  •不开启随路NZ2ND功能（<a href="../cube_store_key_features/NZ2NZ.html">NZ2NZ搬运</a>）：取值范围为mSize∈[0, 65535]。<br><span data-filter="950">  •开启随路<a href="../cube_store_key_features/NZ2ND.html">NZ2ND</a>功能（仅Ascend 950PR/Ascend 950DT支持）：取值范围为mSize∈[0, 8192]。<br></span><strong>注：mSize=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>dstStride</td><td>•不开启NZ2ND功能（<a href="../cube_store_key_features/NZ2NZ.html">NZ2NZ搬运</a>）：目的NZ矩阵中相邻Z排布的起始地址偏移，取值不为0，单位为datablock（32字节）。<br><span data-filter="950">•开启随路<a href="../cube_store_key_features/NZ2ND.html">NZ2ND</a>功能（仅Ascend 950PR/Ascend 950DT支持）：目的ND矩阵每一行中的元素个数，取值不为0 ，单位为element。</span></td></tr><tr><td>srcStride</td><td>源NZ矩阵中相邻Z排布的起始地址偏移，取值范围为srcStride∈[0, 65535]，单位为C0_Size（16*sizeof(T)），T为src的数据类型，其值应填成mSize对16向上取整。</td></tr><tr><td>unitFlag</td><td>unitFlag是一种Mmad指令和Fixpipe指令细粒度的并行，开启该功能后，硬件每计算完一个分形，计算结果就会被搬出。取值说明如下：<br>  • 0（2&#39;b00）：不开启unitFlag。<br>  • 2（2&#39;b10）：开启unitFlag，硬件执行完指令之后，不复位单元标记位。<br>  • 3（2&#39;b11）：开启unitFlag，硬件执行完指令之后，复位单元标记位。<br>开启该功能时，须将Mmad指令和Fixpipe指令的unitFlag值设置为2或3。<br>参数设置方案和特性细节可参考：Mmad计算中关键特性说明的<a href="../mmad_compute_key_features/UnitFlag.html">UnitFlag</a>章节。</td></tr><tr data-filter="950,A3,910b"><td>clipReluPre</td><td>该参数仅在Atlas 200I/500 A2 推理产品支持。<br>用于配置是否开启ClipReLU操作，参数类型为uint8_t，取值如下：0，不开启ClipReLU；1，开启ClipReLU，此时需要调用<a href="../cube_store_aux_config/SetFixPipeClipRelu.html">SetFixPipeClipRelu</a>来设置ClipReLU的最大值。<br>  •该操作在随路量化后进行，quantPre配置后才能使用，当前支持的量化模式有F322F16/DEQF16/VDEQF16/QF322B8_PRE/VQF322B8_PRE/REQ8/VREQ8。<br></td></tr><tr data-filter="950,A3,910b"><td>eltWiseOp</td><td>该参数仅在Atlas 200I/500 A2 推理产品支持。<br>用于配置是否开启Elementwise操作及操作模式。Elementwise操作是指进行随路量化后，可以逐个元素加/减一个LocalTensor，大小为mSize * nSize，具体LocalTensor地址相关参数需要调用<a href="../cube_store_aux_config/SetFixPipeAddr.html">SetFixPipeAddr</a>来设置。<br>eltWiseOp参数类型为uint8_t，取值如下：<br>  • 0：不开启Elementwise；<br>  • 1：Elementwise Addition；<br>  • 2：Elementwise Subtraction。<br></td></tr><tr><td>quantPre</td><td>用于控制量化模式，QuantMode_t类型，具体定义如下：<br>  • half/bfloat16_t输出，此参数需配置为QuantMode_t::F322F16/QuantMode_t::F322BF16。<br>  •配置为scalar量化时，需要调用<a href="../cube_store_aux_config/SetFixpipePreQuantFlag.html">SetFixpipePreQuantFlag</a>接口来设置scalar量化参数。<br>  •配置为tensor量化时，需要调用<a href="../cube_store_aux_config/SetFixPipeConfig.html">SetFixPipeConfig</a>来设置tensor量化参数，其中tensor量化参数需要通过DataCopy从L1 Buffer搬运至Fixpipe Buffer。<br>注：此参数需要用户手动配置，不会自动推导配置对应量化模式。此通路不支持NoQuant模式。<br>enum QuantMode_t<br>{<br> NoQuant, // 不开启量化功能，此通路不支持<br> F322F16, // Float32_2_Float16：float cast成half，cast mode为CAST_RINT模式<br> F322BF16, // Float32_2_BFloat16：float cast成bfloat16_t，cast mode为CAST_RINT模式<br> DEQF16, // DeQuant_Float16：int32_t量化成half，scalar量化<br> VDEQF16, // Vector_DeQuant_Float16：int32_t量化成half，tensor量化<br> QF322B8_PRE, // Quant_Float32_2_B8：float量化成int8_t/uint8_t，scalar量化<br> VQF322B8_PRE, // Vector_Quant_Float32_2_B8：float量化成int8_t/uint8_t，tensor量化<br> REQ8, // ReQuant_int8：int32_t量化成int8_t/uint8_t，scalar量化<br> VREQ8, // Vector_ReQuant_int8：int32_t量化成int8_t/uint8_t，tensor量化<br>};</td></tr><tr><td>reluPre</td><td>用于配置ReLU操作的模式，类型为uint8_t，取值如下：<br>  • 0：不开启ReLU<br>  • 1：Normal ReLU</td></tr><tr data-filter="950"><td>channelSplit</td><td><strong>该参数仅在Ascend 950PR/Ascend 950DT上生效</strong>，仅在NZ格式float类型输出时生效，类型为bool，配置是否开启通道切分功能。<br>  • false：不开启；<br>  • true：开启。<br>针对如下产品型号，此通路上该参数不生效，设置为false即可。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br>Atlas 200I/500 A2 推理产品</td></tr><tr data-filter="950"><td>nz2ndEn</td><td><strong>该参数仅在Ascend 950PR/Ascend 950DT上生效</strong>，类型为bool，配置是否开启NZ2ND的格式转换。<br>如果要开启NZ2ND的功能需要同步调用<a href="../cube_store_aux_config/SetFixpipeNz2ndFlag.html">SetFixpipeNz2ndFlag</a>来设置格式转换的相关配置信息。<br>  • false：不开启；<br>  • true：开启。<br>针对如下产品型号，此通路上该参数不生效，设置为false即可。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品<br>Atlas 200I/500 A2 推理产品</td></tr></tbody></table><h2 id="数据类型">数据类型<a id="zh-cn_topic_0000002511188540_section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><p><strong>源矩阵与目的矩阵支持的数据类型组合</strong></p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，DataCopy接口支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（L1 Buffer）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、half、bfloat16_t、float。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half、int32_t。</td></tr></tbody></table></div><div data-filter="A3"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，DataCopy接口支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（L1 Buffer）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、half、bfloat16_t。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half。</td></tr></tbody></table></div><div data-filter="910b"><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，DataCopy接口支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（L1 Buffer）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、half、bfloat16_t。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half。</td></tr></tbody></table></div><div data-filter="310b"><p>针对Atlas 200I/500 A2 推理产品，DataCopy接口支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（L1 Buffer）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、half、bfloat16_t。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half。</td></tr></tbody></table></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="zh-cn_topic_0000002511188540_section2045914466492"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>对于量化输入为float32数据类型的说明如下： <ul><li>标准的IEEE 754 float32格式为：1bit符号位，8bits指数位，23bits尾数位；当前AI处理器支持的float32格式为：1bit符号位，8bits指数位，10bits尾数位。</li><li>如果用户提供的是标准的IEEE 754 float32输入，API内部会处理成处理器支持的float32格式进行计算，此时如果golden数据生成过程中使用的是标准的IEEE 754 float32数据，则可能引入精度不匹配问题，需要修正golden数据的生成，将量化参数的23bits尾数位的低13bits数据位清零再参与量化计算。</li></ul></li><li>源矩阵NZ格式地址要求64字节对齐，目的矩阵NZ格式地址需要满足32字节对齐。</li><li>当搬出的mSize或nSize中的任意一个值为0时，该指令不会被执行。</li><li>量化和ReLU参数不能为inf/nan和非规格化数。</li><li>目标数据不能有重叠。如果对目的地址有重叠写入，硬件不会报告任何警告和错误，也不保证重叠数据的写入顺序。</li><li>unitFlag特性开启需要配合Mmad同时开启。</li></ul><div data-filter="A3,910b"><ul><li><p>针对如下产品型号，特殊值/边界值约束说明如下：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><p>对于浮点类型inf/nan输入输出，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行设置，控制浮点数量化搬出时的饱和模式：</p><ul><li><p>非饱和模式：CTRL[48]设置成1&#39;b1，inf/nan保持原输出。</p></li><li><p>饱和模式：CTRL[48]设置成1&#39;b0，inf输出会被饱和为±MAX，nan输出会被饱和为0。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 设置CTRL[48]为0，开启浮点数饱和模式</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">AscendCUtils</span><span class="o">::</span><span class="n">SetOverflow</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul><p>对于整数类型只有饱和模式。</p></li></ul></div><div data-filter="950"><ul><li><p>Ascend 950PR/Ascend 950DT特殊值/边界值约束说明：</p><p>对于浮点类型inf/nan输入输出，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行设置，控制浮点数量化搬出时的饱和模式；</p><p>对于fp8_e4m3fn_t类型，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行更精细的设置；</p><ul><li><p>非饱和模式：CTRL[48]设置成1&#39;b1，inf/nan保持原输出。对于fp8_e4m3fn_t类型，若结果的绝对值为inf或大于fp8_e4m3fn_t的最大规格化值，则输出结果为nan。</p></li><li><p>饱和模式：CTRL[48]设置成1&#39;b0，Inf输出会被饱和为±MAX， NaN输出会被饱和为0。对于fp8_e4m3fn_t类型，当CTRL[50]设置成1&#39;b0时，NaN被转换为零，当CTRL[50]设置成1&#39;b1时，NaN保持不变，若结果的绝对值为Inf或大于fp8_e4m3fn_t的最大规格化值，则结果为最大规格化值。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 设置CTRL[48]为0，开启浮点数饱和模式</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">AscendCUtils</span><span class="o">::</span><span class="n">SetOverflow</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul><p>对于整数类型只有饱和模式。</p></li></ul></div><div data-filter="950,A3,910b"><h2 id="调用示例">调用示例<a id="zh-cn_topic_0000002511188540_section088124295117"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>示例：通路L0C Buffer-&gt;L1 Buffer。输入A矩阵和B矩阵的数据类型为half，输出C矩阵为int8_t，不开启NZ2ND的格式转换，开启scalar量化。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>\`\`\`cpp
constexpr uint16_t c0Size = 32;
AscendC::DataCopyCO12DstParams dataCopyParams;

dataCopyParams.dstStride = baseM * c0Size * sizeof(outputType) / AscendC::ONE_BLK_SIZE;
dataCopyParams.mSize = baseM;
dataCopyParams.srcStride = CeilAlign(baseM, CUBE_BLOCK);
dataCopyParams.nSize = baseN;
dataCopyParams.quantPre = QuantMode_t::QF322B8_PRE;

uint64_t deqScalar = static_cast&lt;uint64_t&gt;(*reinterpret_cast&lt;int32_t*&gt;(&amp;quantScalar));
constexpr bool sign = (AscendC::IsSameType&lt;outputType, int8_t&gt;::value) ? true : false;
deqScalar = (deqScalar &amp; ~(static_cast&lt;uint64_t&gt;(1) &lt;&lt; 46)) | (static_cast&lt;uint64_t&gt;(sign) &lt;&lt; 46);
AscendC::SetFixpipePreQuantFlag(deqScalar);
AscendC::DataCopy(c1Local, c, dataCopyParams);
\`\`\`
</code></pre></div></div></article></div>`,1)])])}const A=s(p,[["render",r]]);export{f as __pageData,A as default};
